#include <bits/stdc++.h>
using namespace std;

vector<long long> buildPrefix(const vector<int>& arr) {
    int n = arr.size();
    vector<long long> prefix(n);

    if (n == 0) return prefix;

    prefix[0] = arr[0];

    for (int i = 1; i < n; i++)
        prefix[i] = prefix[i - 1] + arr[i];

    return prefix;
}

long long rangeSum(int l, int r, const vector<long long>& prefix) {
    if (l == 0) return prefix[r];
    return prefix[r] - prefix[l - 1];
}

int main() {
    int n;
    cin >> n;

    vector<int> arr(n);
    for (int i = 0; i < n; i++)
        cin >> arr[i];

    vector<long long> prefix = buildPrefix(arr);

    int q;
    cin >> q;

    while (q--) {
        int l, r;
        cin >> l >> r;
        cout << rangeSum(l, r, prefix) << '
';
    }

    return 0;
}
